{
  "contract": "Yeeter",
  "closure": {
    "site_function": "yeetyeet",
    "site_call": ".call",
    "functions": [
      "<fallback>",
      "yeetyeet"
    ],
    "justification": "These functions can be called during the callback window and affect the exposed storage."
  },
  "protocol": {
    "during_phase": "exposed",
    "allowed_callbacks": [
      "<fallback>"
    ],
    "nesting_bound": {
      "yeetyeet": 1
    }
  },
  "phases": {
    "function": "yeetyeet",
    "pre": {
      "name": "pre",
      "from_marker": "start",
      "to_marker": "before_call"
    },
    "exposed": {
      "name": "exposed",
      "from_marker": "before_call",
      "to_marker": "after_call"
    },
    "post": {
      "name": "post",
      "from_marker": "after_call",
      "to_marker": "end"
    },
    "linearization_point": "after_call"
  },
  "ghost_state": [
    {
      "name": "_sum_deposits",
      "sol_type": "uint256",
      "meaning": "Tracks the sum of all deposits",
      "backed_by_storage": false
    },
    {
      "name": "snapPre",
      "sol_type": "uint256",
      "meaning": "Snapshot of _sum_deposits before the callback",
      "backed_by_storage": false
    },
    {
      "name": "inFlight",
      "sol_type": "uint256",
      "meaning": "Amount of deposits in-flight during the callback",
      "backed_by_storage": false
    }
  ],
  "exposure_invariant": {
    "formula": "_sum_deposits == snapPre + inFlight",
    "stable_formula": "_sum_deposits == snapPre",
    "kind": "conserve"
  },
  "composition": {
    "target_property": "_sum_deposits == balance",
    "rule": "The exposure invariant ensures that the sum of deposits is conserved across the callback window, maintaining the target property."
  }
}
